INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q597478', 'Battle of the Vorskla River', 'The Battle of the Vorskla River was fought on August 12, 1399, between the Tatars of the Golden Horde, under Edigu and Temür Qutlugh, and the armies of Tokhtamysh and a large Crusader force led by Grand Duke Vytautas the Great of Lithuania. The battle ended in a decisive Tatar victory for the Golden Horde.', 1399, 8, 12, NULL, NULL, NULL, 'day', '12 August 1399', 63, 'https://en.wikipedia.org/wiki/Battle_of_the_Vorskla_River'),
  ('Q860981', 'Battle of Khotyn', 'The Battle of Khotyn or Battle of Chocim or Khotyn War (in Turkish: Hotin Muharebesi) was a combined siege and series of battles which took place from 2 September to 9 October 1621 between a Polish–Lithuanian Commonwealth, commanded by the Grand Hetman of Lithuania Jan Karol Chodkiewicz, against an invading Ottoman Imperial army, led by Sultan Osman II, which was stopped until the first autumn snows. On 9 October, due to the lateness of the season and heavy losses – due to failed assaults on Commonwealth fortifications – the Ottomans abandoned their siege and the battle concluded with a…', 1621, 9, 2, 1621, 10, 9, 'day', '2 September 1621 – 9 October 1621', 62, 'https://en.wikipedia.org/wiki/Battle_of_Khotyn_(1621)'),
  ('Q641479', 'Khmelnytsky Uprising', 'The Khmelnytsky Uprising, also known as the Cossack–Polish War, Khmelnytsky insurrection, Cossack Revolution, or, in Ukraine, as the National Liberation War, was a successful Cossack rebellion with elements of a religious war that took place between 1648 and 1657 in the eastern territories of the Polish–Lithuanian Commonwealth. Originating in Dnieper Ukraine, the uprising resulted in a Cossack victory and led to the creation of the Cossack Hetmanate.', 1648, NULL, NULL, 1657, NULL, NULL, 'year', '1648–1657', 71, 'https://en.wikipedia.org/wiki/Khmelnytsky_Uprising'),
  ('Q729936', 'Treaty of Zboriv', 'The Treaty of Zboriv was signed on 18 August 1649, after the Battle of Zboriv when the Crown forces of about 35,000, led by King John II Casimir of Poland, clashed against a combined force of Cossacks and Crimean Tatars, led by Hetman Bohdan Khmelnytsky and Khan İslâm III Giray of Crimea respectively, which numbered about 50,000. The Treaty of Zboriv consisted of two separate agreements between Ukraine and the Commonwealth and between Crimea and the Commonwealth.', 1649, 8, 18, NULL, NULL, NULL, 'day', '18 August 1649', 61, 'https://en.wikipedia.org/wiki/Treaty_of_Zboriv'),
  ('Q593045', 'Battle of Berestechko', 'The Battle of Berestechko (28 June – 10 July 1651) was fought between the Cossack Hetmanate and Crimean Khanate against the Polish–Lithuanian Commonwealth as a part of the Khmelnytsky Uprising. Near the site of the present-day city of Berestechko in Ukraine forces of the Zaporozhian Cossacks and Crimean Tatars under the command of Hetman Bohdan Khmelnytsky, Otaman Tymofiy Khmelnytsky, Colonels Ivan Bohun and Fylon Dzhalaliy with Khan İslâm III Giray and Tugay Bey, who was killed in the battle, were defeated by the Polish–Lithuanian Commonwealth''s forces under the command of the Polish King…', 1651, 6, 28, 1651, 6, 30, 'day', '28 June 1651 – 30 June 1651', 60, 'https://en.wikipedia.org/wiki/Battle_of_Berestechko'),
  ('Q525758', 'Treaty of Pereyaslav', 'The Pereiaslav Agreement or Pereyaslav Agreement (Ukrainian: Переяславська рада, romanized: Pereiaslavska Rada, lit. ''Pereiaslav Council'', Russian: Переяславская рада) was an official meeting that convened for a ceremonial pledge of allegiance by Zaporozhian Cossacks to Russian tsar Alexis (r. 1645–1676) in the town of Pereiaslav in central Ukraine, in January 1654. The ceremony took place concurrently with ongoing negotiations that started on the initiative of Hetman Bohdan Khmelnytsky to address the issue of the Cossack Hetmanate with the ongoing Khmelnytsky Uprising against the…', 1654, NULL, NULL, NULL, NULL, NULL, 'year', '1654', 71, 'https://en.wikipedia.org/wiki/Pereiaslav_Agreement'),
  ('Q386038', 'Treaty of Hadiach', 'The Treaty of Hadiach (Polish: Unia hadziacka; Ukrainian: Гадяцький договір, romanized: Hadyatsʹkyy dohovir) was a treaty signed on 16 September 1658 in Hadiach, Cossack Hetmanate (present-day Ukraine) between representatives of the Polish–Lithuanian Commonwealth (Stanisław Kazimierz Bieniewski representing Poland and Kazimieras Liudvikas Jevlaševskis representing Lithuania) and Ukrainian Cossacks (represented by Hetman Ivan Vyhovsky and starshina Yuri Nemyrych, the architect of the treaty, and Pavlo Teteria). It was designed to elevate the Cossacks (Ruthenians) to a position equal to that…', 1658, 9, 16, NULL, NULL, NULL, 'day', '16 September 1658', 62, 'https://en.wikipedia.org/wiki/Treaty_of_Hadiach'),
  ('Q3636391', 'Battle of Khotyn', 'The Battle of Khotyn or Battle of Chocim, also known as the Hotin War, took place on 11 November 1673 in Khotyn, where the forces of the Polish–Lithuanian Commonwealth under the Grand Hetman of the Polish Crown John Sobieski defeated Ottoman Empire forces, with Moldavian and Wallachian regiments, led by Hüseyin Pasha. It reversed the fortunes of the previous year, when Commonwealth weakness led to the signing of the Treaty of Buchach, and allowed John Sobieski to win the upcoming royal election and become the King of Poland.', 1673, 11, 11, NULL, NULL, NULL, 'day', '11 November 1673', 59, 'https://en.wikipedia.org/wiki/Battle_of_Khotyn_(1673)'),
  ('Q660004', 'Second Russo-Turkish War', 'The Russo-Turkish War of 1672–1681, also known as the Chyryhyn campaigns, was a war between the Tsardom of Russia and Ottoman Empire, caused by Turkish expansionism in the second half of the 17th century. Is the largest and one of the most important series of military campaigns before the Great Turkish War.', 1676, NULL, NULL, 1681, NULL, NULL, 'year', '1676–1681', 69, 'https://en.wikipedia.org/wiki/Russo-Turkish_War_(1672%E2%80%931681)'),
  ('Q152486', 'Battle of Poltava', 'The Battle of Poltava fought on 8 July 1709, was the decisive and largest battle of the Great Northern War. A Russian army under the command of Tsar Peter I defeated a Swedish army commanded by Carl Gustaf Rehnskiöld.', 1709, 6, 27, NULL, NULL, NULL, 'day', '27 June 1709', 78, 'https://en.wikipedia.org/wiki/Battle_of_Poltava'),
  ('Q770536', 'Battle of Inkerman', 'The Battle of Inkerman was fought during the Crimean War on 5 November 1854 by the allied armies of the United Kingdom and France against the Imperial Russian Army. The battle broke the will of the Russian Army to defeat the allies in the field, and was followed by the siege of Sevastopol.', 1854, 11, 5, NULL, NULL, NULL, 'day', '5 November 1854', 61, 'https://en.wikipedia.org/wiki/Battle_of_Inkerman'),
  ('Q815216', 'Siege of Sevastopol', 'The Siege of Sevastopol (at the time called in English the Siege of Sebastopol) lasted from October 1854 until September 1855, during the Crimean War. The allies (French, Sardinian, Ottoman, and British) landed at Eupatoria on 14 September 1854, intending to make a triumphal march to Sevastopol, the capital of the Crimea, with 50,000 men.', 1854, NULL, NULL, 1855, 9, 9, 'year', '1854 – 9 September 1855', 65, 'https://en.wikipedia.org/wiki/Siege_of_Sevastopol_(1854%E2%80%931855)'),
  ('Q659246', 'Battle of Galicia', 'The Battle of Galicia, also known as the Great Battle of Galicia, was a major battle between Russia and Austria-Hungary during the early stages of World War I in 1914. In the course of the battle, the Austro-Hungarian armies were severely defeated in several encounters and forced out of Galicia, while the Russians captured Lemberg (now Lviv) and, for approximately nine months, ruled Eastern Galicia until their defeat at Gorlice and Tarnów.', 1914, 8, 23, 1914, 9, 11, 'day', '23 August 1914 – 11 September 1914', 69, 'https://en.wikipedia.org/wiki/Battle_of_Galicia'),
  ('Q2419855', 'Ukrainian–Soviet War', 'The Ukrainian–Soviet War (Ukrainian: українсько-радянська війна, romanized: ukrainsko-radianska viina) is the term commonly used in post-Soviet Ukraine for the events taking place between 1917 and 1921, nowadays regarded essentially as a war between the Ukrainian People''s Republic and the Bolsheviks (Russian SFSR and Ukrainian SSR). The war ensued soon after the October Revolution when Lenin dispatched Antonov''s expeditionary group to Ukraine and Southern Russia.', 1917, 11, 8, 1921, NULL, NULL, 'day', '8 November 1917 – 1921', 62, 'https://en.wikipedia.org/wiki/Ukrainian%E2%80%93Soviet_War'),
  ('Q2479606', 'Ukrainian War of Independence', 'The Ukrainian War of Independence, also referred to as the Ukrainian–Soviet War in Ukraine, lasted from March 1917 to November 1921 and was part of the wider Russian Civil War. It saw the establishment and development of an independent Ukrainian republic, most of which was absorbed into the Ukrainian Soviet Socialist Republic between 1919 and 1920.', 1917, 11, 8, 1921, 11, 17, 'day', '8 November 1917 – 17 November 1921', 69, 'https://en.wikipedia.org/wiki/Ukrainian_War_of_Independence'),
  ('Q154860', 'Siege of Sevastopol', 'The siege of Sevastopol, also known as the defence of Sevastopol (Russian: Оборона Севастополя, romanized: Oborona Sevastopolya) or the Battle for Sevastopol (German: Schlacht um Sewastopol; Romanian: Bătălia de la Sevastopol; Russian: Битва за Севастополь, romanized: Bitva za Sevastopol''), was a military engagement that took place on the Eastern Front of the Second World War. The campaign was fought by the Axis powers of Germany and Romania against the Soviet Union for control of Sevastopol, a port in Crimea on the Black Sea.', 1941, 10, 30, 1942, 7, 4, 'day', '30 October 1941 – 4 July 1942', 71, 'https://en.wikipedia.org/wiki/Siege_of_Sevastopol_(1941%E2%80%931942)'),
  ('Q162284', 'Battle of Kiev', 'The First Battle of Kiev or Kiev operation, known as the Battle of Kiev on the German side (German: Schlacht bei Kiew), was a major battle that resulted in an encirclement of Soviet troops in the vicinity of Kiev during World War II, the capital and most populous city of the Ukrainian Soviet Socialist Republic. This encirclement is the largest in the history of warfare by number of troops.', 1941, NULL, NULL, 1941, 9, 26, 'year', '1941', 71, 'https://en.wikipedia.org/wiki/Battle_of_Kiev_(1941)'),
  ('Q682409', 'Siege of Odesa 1941', 'The siege of Odessa, known to the Soviets as the defence of Odessa, lasted from 8 August until 16 October 1941, during the early phase of Operation Barbarossa, the Axis invasion of the Soviet Union during World War II. Odessa was a port on the Black Sea in the Ukrainian SSR. On 22 June 1941, the Axis powers invaded the Soviet Union. In August, Odessa became a target of the Romanian 4th Army and elements of the German 11th Army.', 1941, 8, 8, 1941, 10, 16, 'day', '8 August 1941 – 16 October 1941', 68, 'https://en.wikipedia.org/wiki/Siege_of_Odessa'),
  ('Q697658', 'First Battle of Kharkov', 'The First Battle of Kharkov was a battle that took place from 20 to 24 October 1941 for control of the city of Kharkov, located in the Ukrainian SSR, during the final stage of Operation Barbarossa. The battle was fought between the German 6th Army, part of Army Group South, and the Soviet Southwestern Front.', 1941, 10, 20, 1941, 10, 24, 'day', '20 October 1941 – 24 October 1941', 68, 'https://en.wikipedia.org/wiki/First_Battle_of_Kharkov'),
  ('Q700937', 'Crimean Campaign', 'The Crimean campaign was conducted by the Axis as part of Operation Barbarossa during World War II. The invading force was led by Germany with support from Romania and Italy, while the Soviet Union took up defensive positions throughout the Crimean Peninsula. The Axis offensive routed the Red Army and enabled the three-year-long German occupation of Crimea.', 1941, 10, 18, 1942, 7, 4, 'day', '18 October 1941 – 4 July 1942', 61, 'https://en.wikipedia.org/wiki/Crimean_campaign'),
  ('Q708213', 'Battle of Brody', 'The Battle of Brody (other names in use include Battle of Dubna, Battle of Dubno, Battle of Rovne, Battle of Rovne-Brody) was a tank battle fought between the 1st Panzer Group''s III Army Corps and XLVIII Army Corps (Motorized) and five mechanized corps of the Soviet 5th Army and 6th Army in the triangle formed by the towns of Dubno, Lutsk and Brody between 23 and 30 June 1941. It was one of the most intense armored engagements in the opening phase of Operation Barbarossa, and some say that it may surpass the more famous Battle of Prokhorovka.', 1941, 6, 23, 1941, 6, 30, 'day', '23 June 1941 – 30 June 1941', 64, 'https://en.wikipedia.org/wiki/Battle_of_Brody_(1941)'),
  ('Q155620', 'Second Battle of Kharkov', 'The Second Battle of Kharkov or Operation Fredericus was an Axis counter-offensive in the region around Kharkov against the Red Army Izium bridgehead offensive conducted 12–28 May 1942, on the Eastern Front during World War II. Its objective was to eliminate the Izium bridgehead over Seversky Donets or the "Barvenkovo bulge" (Russian: Барвенковский выступ, romanized: Barvenkovsky vystup) which was one of the Soviet offensive''s staging areas. After a winter counter-offensive that drove German troops away from Moscow but depleted the Red Army''s reserves, the Kharkov offensive was a new Soviet…', 1942, 5, 12, 1942, 5, 29, 'day', '12 May 1942 – 29 May 1942', 71, 'https://en.wikipedia.org/wiki/Second_Battle_of_Kharkov'),
  ('Q695020', 'Massacres of Poles in Volhynia and Eastern Galicia', 'The massacres of Poles in Volhynia and Eastern Galicia were carried out in German-occupied Poland by the Ukrainian Insurgent Army (UPA), with the support of parts of the local Ukrainian population, against the Polish minority in Volhynia, Eastern Galicia, parts of Polesia, and the Lublin region from 1943 to 1945. The UPA''s actions resulted in up to 100,000 Polish deaths.', 1942, NULL, NULL, 1944, NULL, NULL, 'year', '1942–1944', 72, 'https://en.wikipedia.org/wiki/Massacres_of_Poles_in_Volhynia_and_Eastern_Galicia'),
  ('Q157873', 'Third Battle of Kharkov', 'The Third Battle of Kharkov was a series of battles on the Eastern Front of World War II, undertaken by Nazi Germany''s Army Group South against the Soviet Red Army, around the city of Kharkov from 19 February to 15 March 1943. Known to the German side as the Donets Campaign and in the Soviet Union as the Donbass and Kharkov operations, the German counterstrike led to the recapture of the cities of Kharkov and Belgorod.', 1943, 2, 19, 1943, 3, 15, 'day', '19 February 1943 – 15 March 1943', 71, 'https://en.wikipedia.org/wiki/Third_Battle_of_Kharkov'),
  ('Q700960', 'Battle of Kiev', 'The Second Battle of Kiev, known on the German side as the Defensive battle in the Kiev-Zhitomir area (German: Abwehrschlacht im Raum Kiew-Shitomir), was a part of a much wider Soviet offensive in Ukraine known as the Battle of the Dnieper involving three strategic operations by the Soviet Red Army and its Czechoslovak units and one operational counterattack by the Wehrmacht, which took place between 4 November and 22 December 1943. Following the Battle of Kursk, the Red Army launched the Belgorod-Kharkov Offensive Operation, pushing Army Group South (Erich von Manstein) back towards the…', 1943, NULL, NULL, 1943, 12, 22, 'year', '1943', 64, 'https://en.wikipedia.org/wiki/Battle_of_Kiev_(1943)'),
  ('Q509417', 'Battle of the Korsun–Cherkassy Pocket', 'The Battle of Korsun–Cherkassy (Russian: Корсунь-Шевченковская операция; Ukrainian: Корсунь-Шевченківська операція), also known as the Battle of the Korsun–Cherkassy Pocket, was a World War II battle fought from 24 January to 16 February 1944 in the course of the Soviet Dnieper–Carpathian offensive in Ukraine, following the Korsun–Shevchenkovsky offensive. In the battle, the 1st and 2nd Ukrainian Fronts, commanded, respectively, by Nikolai Vatutin and Ivan Konev, encircled German forces of Army Group South in a pocket near the Dnieper River.', 1944, 1, 24, 1944, 2, 17, 'day', '24 January 1944 – 17 February 1944', 64, 'https://en.wikipedia.org/wiki/Battle_of_Korsun%E2%80%93Cherkassy'),
  ('Q76986', 'Belovezh Accords', 'The Agreement on the creation of the Commonwealth of Independent States (officially), or unofficially the Minsk Agreement and best known as the Belovezha Accords, is the agreement declaring that the Soviet Union (USSR) had effectively ceased to exist and establishing the Commonwealth of Independent States (CIS) in its place as an organization created by the same Union Republics. The documentation was signed at the state dacha near Viskuli in Belovezhskaya Pushcha, Belarus on 8 December 1991, by leaders of three of the four republics (except for the defunct Transcaucasian SFSR) which had…', 1991, 12, 8, NULL, NULL, NULL, 'day', '8 December 1991', 71, 'https://en.wikipedia.org/wiki/Belovezha_Accords'),
  ('Q836386', 'Orange Revolution', 'The Orange Revolution (Ukrainian: Помаранчева революція, romanized: Pomarancheva revoliutsiia) was a series of protests that led to political upheaval in Ukraine from late November 2004 to January 2005. It gained momentum primarily due to the initiative of the general population, sparked by the aftermath of the 2004 Ukrainian presidential election runoff which was claimed to be marred by massive corruption, voter intimidation, and electoral fraud.', 2004, 11, 22, 2005, 1, 23, 'day', '22 November 2004 – 23 January 2005', 80, 'https://en.wikipedia.org/wiki/Orange_Revolution'),
  ('Q15224558', 'Euromaidan', 'Euromaidan (; Ukrainian: Євромайдан, romanised: Yevromaidan, IPA: [ˌjɛu̯romɐjˈdɑn], lit. ''Euro Square''), or the Maidan Uprising, was a wave of demonstrations and civil unrest in Ukraine, which began on 21 November 2013 with large protests in Maidan Nezalezhnosti (Independence Square) in Kyiv. The protests were sparked by President Viktor Yanukovych''s sudden decision not to sign the European Union–Ukraine Association Agreement, instead choosing closer ties to Russia and the Eurasian Economic Union.', 2010, NULL, NULL, 2014, 2, 23, 'decade', '2010s – 23 February 2014', 82, 'https://en.wikipedia.org/wiki/Euromaidan'),
  ('Q15733401', 'Revolution of Dignity', 'The Revolution of Dignity (Ukrainian: Революція гідності, romanized: Revoliutsiia hidnosti), also known as the Maidan Revolution or the Ukrainian Revolution, took place in Ukraine in February 2014 at the end of the Euromaidan protests. Scores of protesters were killed by government forces during clashes in the capital Kyiv.', 2010, NULL, NULL, 2014, 2, 23, 'decade', '2010s – 23 February 2014', 73, 'https://en.wikipedia.org/wiki/Revolution_of_Dignity'),
  ('Q15838763', '2014 Crimean status referendum', 'A disputed referendum concerning the status of Crimea was conducted in the Autonomous Republic of Crimea and the city of Sevastopol (both subdivisions of Ukraine) on March 16, 2014, after Russian forces seized control of Crimea. The referendum was a step in the process of Russia annexing Crimea.', 2014, 3, 16, NULL, NULL, NULL, 'day', '16 March 2014', 71, 'https://en.wikipedia.org/wiki/2014_Crimean_status_referendum'),
  ('Q15871713', '2014 pro-Russian unrest in Ukraine', 'From the end of February 2014, in the aftermath of the Euromaidan and the Revolution of Dignity, which resulted in the ousting of Russian-leaning Ukrainian president Viktor Yanukovych, demonstrations by Russian-backed, pro-Russian, and anti-government groups (as well as pro-government demonstrations) took place in Crimea, Donetsk, Luhansk, Kharkiv, and Odesa. The unrest, which was supported by the Russian military and intelligence services, belongs to the early stages of the Russo-Ukrainian war.', 2014, 2, 23, 2014, 6, 22, 'day', '23 February 2014 – 22 June 2014', 68, 'https://en.wikipedia.org/wiki/2014_pro-Russian_unrest_in_Ukraine'),
  ('Q15920546', 'Russian annexation of Crimea', 'In February and March 2014, Russia invaded the Crimean Peninsula of Ukraine, occupied it, and then annexed it after an illegitimate referendum. This took place amid the uncertainty that immediately followed Ukraine''s Revolution of Dignity.', 2014, NULL, NULL, 2014, 3, 26, 'year', '2014', 81, 'https://en.wikipedia.org/wiki/2014_Russian_annexation_of_Crimea'),
  ('Q16335075', 'War in Donbas', 'The war in Donbas, also called the Donbas war, was a phase of the Russo-Ukrainian war in the eastern Donbas region of Ukraine. The war began in April 2014, when Russian-backed paramilitaries began an uprising against the Ukrainian government, seized territory and declared independent states.', 2014, 4, 12, 2022, 2, 24, 'day', '12 April 2014 – 24 February 2022', 81, 'https://en.wikipedia.org/wiki/War_in_Donbas'),
  ('Q112222097', 'child abductions in the Russo-Ukrainian war', 'During the Russo-Ukrainian war, Russia has forcibly transferred almost 20,000 Ukrainian children to areas under its control, assigned them Russian citizenship, forcibly adopted them into Russian families, and created obstacles for their reunification with their parents and homeland. The International Criminal Court (ICC) has issued arrest warrants for President of Russia Vladimir Putin (who has explicitly supported the forced adoptions, including by enacting legislation to facilitate them) and Children''s Rights Commissioner Maria Lvova-Belova for their alleged involvement.', 2014, NULL, NULL, NULL, NULL, NULL, 'year', '2014', 67, 'https://en.wikipedia.org/wiki/Child_abductions_in_the_Russo-Ukrainian_war'),
  ('Q59199697', 'Kerch Strait incident', 'The Kerch Strait incident was an international incident that occurred on 25 November 2018 in the Kerch Strait, during which the Russian Federal Security Service (FSB) coast guard fired upon and captured three Ukrainian Navy vessels after they attempted to transit from the Black Sea into the Sea of Azov through the strait on their way to the port of Mariupol. It was the first time that Russian forces had openly engaged Ukrainian forces during the Russo-Ukrainian War.', 2018, 11, 25, NULL, NULL, NULL, 'day', '25 November 2018', 67, 'https://en.wikipedia.org/wiki/Kerch_Strait_incident'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe'),
  ('Q111025771', 'eastern front of the Russian invasion of Ukraine', 'Ukraine''s easternmost regions, Donetsk, Luhansk, and Kharkiv, have been the site of an ongoing theatre of operation since the start of the Russo-Ukrainian war in February 2022. The battle of Donbas was a major offensive in the eastern theatre that took place in mid-2022.', 2020, NULL, NULL, NULL, NULL, NULL, 'decade', '2020s', 61, 'https://en.wikipedia.org/wiki/Eastern_front_of_the_Russo-Ukrainian_war_(2022%E2%80%93present)'),
  ('Q111383245', 'Battle of Avdiivka', 'The Battle of Avdiivka was a major battle between the Russian and Ukrainian Armed Forces for control of Avdiivka, a city in Donetsk Oblast, during the Russo-Ukrainian war (2022–present). After more than a year and a half of intermittent fighting along the city''s outskirts, Russian forces launched an offensive to capture Avdiivka on 10 October 2023, resulting in what was considered one of the bloodiest and fiercest battles of the war.', 2020, NULL, NULL, 2024, 2, 17, 'decade', '2020s – 17 February 2024', 64, 'https://en.wikipedia.org/wiki/Battle_of_Avdiivka_(2023%E2%80%932024)'),
  ('Q110999040', 'full-scale Russo-Ukrainian war', 'On 24 February 2022, Russia invaded Ukraine, starting the largest and deadliest war in Europe since World War II, in a major escalation of the existing war between the two countries that began when Russia attacked Ukraine in 2014. The fighting has caused hundreds of thousands of military casualties and tens of thousands of Ukrainian civilian casualties.', 2022, 2, 24, NULL, NULL, NULL, 'day', '24 February 2022', 98, 'https://en.wikipedia.org/wiki/Russo-Ukrainian_war_(2022%E2%80%93present)'),
  ('Q111012383', 'Capture of Chernobyl', 'During the 2022 Russian invasion of Ukraine, the Chernobyl Exclusion Zone was captured on 24 February, the first day of the invasion, by the Russian Armed Forces, who entered Ukrainian territory from neighbouring Belarus and seized the entire area of the Chernobyl Nuclear Power Plant by the end of that day. On 7 March, it was reported that around 300 people (100 workers and 200 security guards for the plant) were trapped and had been unable to leave the power plant since its capture.', 2022, 2, 24, NULL, NULL, NULL, 'day', '24 February 2022', 69, 'https://en.wikipedia.org/wiki/Capture_of_Chernobyl'),
  ('Q111012552', 'Snake Island campaign', 'The Snake Island campaign was a Russian military attack on and occupation of Snake Island, a small, strategically located Ukrainian island in the Black Sea. On 24 February 2022, the first day of the 2022 Russian invasion of Ukraine, the Russian Navy attacked Snake Island and captured it along with its garrison, beginning a 126-day military occupation.', 2022, 2, 24, NULL, NULL, NULL, 'day', '24 February 2022', 71, 'https://en.wikipedia.org/wiki/Snake_Island_campaign'),
  ('Q111013267', 'Battle of Antonov Airport', 'The Battle of Antonov Airport, also known as the Battle of Hostomel Airport, was a military engagement which occurred at Antonov Airport in Hostomel, Kyiv Oblast, during the Kyiv offensive of the Russian invasion of Ukraine. On 24 February 2022, a few hours after the president of Russia, Vladimir Putin announced the beginning of a "special military operation" in Ukraine, Russian troops of the Russian Airborne Forces (VDV) made an air assault on Antonov Airport with the objective of capturing it.', 2022, 2, 24, 2022, 2, 25, 'day', '24 February 2022 – 25 February 2022', 67, 'https://en.wikipedia.org/wiki/Battle_of_Antonov_Airport'),
  ('Q111013514', 'Battle of Sumy', 'On 24 February 2022, the first day of the Russian invasion of Ukraine, a military engagement took place in the city of Sumy, located near the Russia–Ukraine border. Ukrainian paratroopers and territorial defense forces began engaging Russian forces within the city, resulting in heavy urban fighting and the destruction of a Russian tank column.', 2022, 2, 24, 2022, 2, 25, 'day', '24 February 2022 – 25 February 2022', 63, 'https://en.wikipedia.org/wiki/Battle_of_Sumy'),
  ('Q111013915', 'Siege of Chernihiv', 'The Siege of Chernihiv was a military engagement in the city of Chernihiv, in Chernihiv Oblast in the north of Ukraine. It began on 24 February 2022, as part of the northern Ukraine offensive, during the 2022 Russian invasion of Ukraine.', 2022, 2, 24, NULL, NULL, NULL, 'day', '24 February 2022', 64, 'https://en.wikipedia.org/wiki/Siege_of_Chernihiv'),
  ('Q111014380', 'Battle of Kharkiv', 'The Battle of Kharkiv was a military engagement that took place from February to May 2022 in and around the city of Kharkiv in Ukraine, as part of the eastern Ukraine offensive during the Russian invasion of Ukraine. Kharkiv, located just 30 kilometres (19 mi) south of the Russia–Ukraine border and a predominately Russian-speaking city, is the second-largest city in Ukraine and was considered a major target for the Russian military early in the invasion.', 2022, 2, 24, NULL, NULL, NULL, 'day', '24 February 2022', 68, 'https://en.wikipedia.org/wiki/Battle_of_Kharkiv_(2022)'),
  ('Q111014904', 'Battle of Kherson', 'The Battle of Kherson took place on 1 March 2022 on the southern front of the Russo-Ukrainian war. Russian forces captured the city on 1 March 2022 after brief combat with local territorial defense fighters, and then began a military occupation of the city.', 2022, 2, 24, 2022, 3, 2, 'day', '24 February 2022 – 2 March 2022', 68, 'https://en.wikipedia.org/wiki/Battle_of_Kherson'),
  ('Q111017791', 'Siege of Mariupol', 'The siege of Mariupol began on 24 February 2022, as part of the Russian invasion of Ukraine, and lasted until 20 May. It saw fighting between the Russian Armed Forces (alongside the Donetsk People''s Republic People''s Militia) and the Ukrainian Armed Forces for control over the city of Mariupol in southeastern Ukraine.', 2022, 2, 25, 2022, 5, 20, 'day', '25 February 2022 – 20 May 2022', 75, 'https://en.wikipedia.org/wiki/Siege_of_Mariupol'),
  ('Q111018336', 'Battle of Vasylkiv', 'Battle in the 2022 Russian invasion of Ukraine.', 2022, 2, 26, NULL, NULL, NULL, 'day', '26 February 2022', 64, 'https://en.wikipedia.org/wiki/Battle_of_Vasylkiv'),
  ('Q111018339', 'Battle of Konotop', 'Battle in the 2022 Russian invasion of Ukraine.', 2022, 2, 24, 2022, 2, 26, 'day', '24 February 2022 – 26 February 2022', 61, 'https://en.wikipedia.org/wiki/Battle_of_Konotop_(2022)'),
  ('Q111020511', 'Battle of Mykolaiv', 'The battle of Mykolaiv started on the night of 26 February 2022, as part of the southern Ukraine campaign during the Russian invasion of Ukraine. It ended with Russian forces being repulsed from the city in March, and by April all but a few of its surrounding villages were back under Ukrainian control.', 2022, 2, 25, 2022, 4, 8, 'day', '25 February 2022 – 8 April 2022', 61, 'https://en.wikipedia.org/wiki/Battle_of_Mykolaiv'),
  ('Q111032201', 'Battle of Okhtyrka', 'On 24 February 2022, as part of the 2022 Russian invasion of Ukraine, the Russian military crossed the Russia–Ukraine and Belarus–Ukraine borders into northern Ukraine, entering the oblasts (regions) of Kyiv, Chernihiv, Sumy, and Zhytomyr. The Russian operations in northern Ukraine were initially launched as an attempt to capture Kyiv, the capital of Ukraine and the seat of the Ukrainian government.', 2022, 2, 24, NULL, NULL, NULL, 'day', '24 February 2022', 61, 'https://en.wikipedia.org/wiki/Battle_of_Okhtyrka'),
  ('Q111037776', 'Battle of Enerhodar', 'On 4 March 2022, a military engagement took place between the Russian Armed Forces and the Armed Forces of Ukraine over the city of Enerhodar in Zaporizhzhia Oblast, on the southern front of the Russian invasion of Ukraine. Enerhodar is the location of the Zaporizhzhia Nuclear Power Plant, which generates nearly half of the country''s electricity derived from nuclear power and more than a fifth of total electricity generated in Ukraine, as well as a nearby thermal power station.', 2022, NULL, NULL, 2022, 3, 4, 'year', '2022', 61, 'https://en.wikipedia.org/wiki/Battle_of_Enerhodar'),
  ('Q111078529', 'Battle of Sievierodonetsk', 'The Battle of Sievierodonetsk was a military engagement in the wider battle of Donbas of the eastern Ukraine campaign during the Russian invasion of Ukraine. The city of Sievierodonetsk acted as the administrative centre of unoccupied Luhansk Oblast prior to the invasion.', 2022, NULL, NULL, 2022, 6, 25, 'year', '2022', 65, 'https://en.wikipedia.org/wiki/Battle_of_Sievierodonetsk_(2022)'),
  ('Q111144576', 'Battle of Irpin', 'As part of the Russian offensive on Kyiv during the Russian invasion of Ukraine, a battle took place for control of the city of Irpin. The combatants were elements of the Russian Armed Forces and Ukrainian Ground Forces.', 2022, 2, 27, 2022, 3, 28, 'day', '27 February 2022 – 28 March 2022', 60, 'https://en.wikipedia.org/wiki/Battle_of_Irpin'),
  ('Q111467700', 'Bucha massacre', 'The Bucha massacre was the mass murder of Ukrainian civilians and prisoners of war by the Russian Armed Forces during the fight for and occupation of the city of Bucha as part of the Russian invasion of Ukraine. Photographic and video evidence of the massacre emerged on 1 April 2022, after Russian forces withdrew from the city.', 2022, 3, 31, 2022, 3, 31, 'day', '31 March 2022', 81, 'https://en.wikipedia.org/wiki/Bucha_massacre'),
  ('Q112114958', 'Battle of Bakhmut', 'The Battle of Bakhmut was a major battle between the Russian Armed Forces and the Ukrainian Armed Forces for control of the city of Bakhmut, during the eastern front, a theatre of the Russo-Ukrainian war. It is regarded by some military analysts to be the bloodiest battle since World War II. The shelling of Bakhmut began in May 2022, and Russian offensives on the distant approaches to the city began in early July.', 2022, 8, 9, 2024, 1, 7, 'day', '9 August 2022 – 7 January 2024', 71, 'https://en.wikipedia.org/wiki/Battle_of_Bakhmut'),
  ('Q113865480', '2022 Kharkiv counteroffensive', 'On 6 September 2022, the Armed Forces of Ukraine launched a major counteroffensive against the Russian military during the Russo-Ukrainian war. As Ukraine announced the start of the Kherson counteroffensive in southern Ukraine in late August, Ukrainian forces also began a second counteroffensive in early September in Kharkiv Oblast, in eastern Ukraine.', 2022, 9, 6, 2022, 10, 2, 'day', '6 September 2022 – 2 October 2022', 61, 'https://en.wikipedia.org/wiki/2022_Kharkiv_counteroffensive'),
  ('Q119123254', 'destruction of the Kakhovka Dam', 'The Kakhovka Dam was breached in the early hours of 6 June 2023, causing extensive flooding along the lower Dnieper river, also called the Dnipro, in Kherson Oblast. The dam was under the control of the Russian military, which had seized it in the early days of the Russian invasion of Ukraine.', 2023, 6, 6, NULL, NULL, NULL, 'day', '6 June 2023', 68, 'https://en.wikipedia.org/wiki/Destruction_of_the_Kakhovka_Dam');
